116. export class SemanticInputRuntime {
117.   private readonly state = new SemanticInputState();
118.   private readonly gamepadSnapshots = new Map<number, GamepadSnapshot>();
119.   private readonly syntheticEvents = new WeakSet<Event>();
120.   private readonly heldSyntheticKeys = new Map<string, KeyDescriptor>();
121.   private readonly syntheticKeyOwnership = new InputKeyOwnership();
122.   private animationFrame = 0;
123.   private activeSceneKey = "";
124.   private activeContext: InputContext = "overlay";
125.   private touchRoot: HTMLDivElement | null = null;
126.   private cursor: HTMLDivElement | null = null;
127.   private cursorX = 0;
128.   private cursorY = 0;
129.   private cursorActive = false;
130.   private gamepadConnected = false;
131.   private unsubscribePreferences: (() => void) | null = null;
132.   private unsubscribeFeatures: (() => void) | null = null;
133. 
134.   constructor(private readonly game: Phaser.Game) {}
135. 
136.   start(): void {
137.     window.addEventListener("keydown", this.handleKeyDown, true);
138.     window.addEventListener("keyup", this.handleKeyUp, true);
139.     window.addEventListener("gamepadconnected", this.handleGamepadConnection);
140.     window.addEventListener("gamepaddisconnected", this.handleGamepadConnection);
141.     window.addEventListener("blur", this.handleBlur);
142.     document.addEventListener("visibilitychange", this.handleVisibility);
143.     this.game.canvas.addEventListener("pointerdown", this.handlePointerSource, true);
144.     this.game.canvas.addEventListener("pointermove", this.handlePointerSource, true);
145.     this.createTouchControls();
146.     this.createCursor();
147.     this.unsubscribePreferences = gamePreferences.subscribe(() => {
148.       this.applyControlPreferences();
149.     });
150.     this.unsubscribeFeatures = featureAvailability.subscribe(() => {
151.       this.applyFeatureAvailability();
152.     });
153.     this.applyControlPreferences();
154.     this.animationFrame = window.requestAnimationFrame(this.poll);
155.   }
156. 
157.   destroy(): void {
158.     window.cancelAnimationFrame(this.animationFrame);
159.     window.removeEventListener("keydown", this.handleKeyDown, true);
160.     window.removeEventListener("keyup", this.handleKeyUp, true);
161.     window.removeEventListener("gamepadconnected", this.handleGamepadConnection);
162.     window.removeEventListener("gamepaddisconnected", this.handleGamepadConnection);
163.     window.removeEventListener("blur", this.handleBlur);
164.     document.removeEventListener("visibilitychange", this.handleVisibility);
165.     this.game.canvas.removeEventListener("pointerdown", this.handlePointerSource, true);
166.     this.game.canvas.removeEventListener("pointermove", this.handlePointerSource, true);
167.     this.unsubscribePreferences?.();
168.     this.unsubscribePreferences = null;
169.     this.unsubscribeFeatures?.();
170.     this.unsubscribeFeatures = null;
171.     this.touchRoot?.remove();
172.     this.cursor?.remove();
173.     this.touchRoot = null;
174.     this.cursor = null;
175.     this.clearAll();
176.   }
177. 
178.   private readonly poll = (timestamp: number): void => {
179.     const sceneKey = this.getActiveSceneKey();
180.     const context = this.getContext();
181.     if (sceneKey !== this.activeSceneKey || context !== this.activeContext) {
182.       this.closeMobileTextInput();
183.       this.releaseAllSyntheticKeys();
184.       this.state.clear();
185.       this.activeSceneKey = sceneKey;
186.       this.activeContext = context;
187.       this.cursorActive = false;
188.       this.updateCursor();
189.     }
190.     this.pollGamepads(timestamp);
191.     for (const event of this.state.update(timestamp)) this.dispatch(event);
192.     this.animationFrame = window.requestAnimationFrame(this.poll);
193.   };
194. 
195.   private readonly handleKeyDown = (event: KeyboardEvent): void => {
196.     if (this.syntheticEvents.has(event) || event.repeat) return;
197.     inputSource.set("keyboard");
198.     this.updatePresentation("keyboard");
199.   };
200. 
201.   private readonly handleKeyUp = (event: KeyboardEvent): void => {
202.     if (this.syntheticEvents.has(event)) return;
203.   };
204. 
205.   private readonly handlePointerSource = (event: PointerEvent): void => {
206.     if (this.syntheticEvents.has(event)) return;
207.     const source: InputSource = event.pointerType === "touch"
208.       ? "touch"
209.       : "pointer";
210.     inputSource.set(source);
211.     this.updatePresentation(source);
212.   };
213. 
214.   private readonly handleGamepadConnection = (): void => {
215.     this.gamepadConnected = navigator.getGamepads().some(Boolean);
216.     if (!this.gamepadConnected) {
217.       const released = this.state.releaseMatching("gamepad:");
218.       for (const entry of released) this.releaseSyntheticToken(entry.token);
219.       this.gamepadSnapshots.clear();
220.     }
221.     this.applyControlPreferences();
222.   };
223. 
224.   private readonly handleBlur = (): void => {
225.     this.clearAll();
226.   };
227. 
228.   private readonly handleVisibility = (): void => {
229.     if (document.visibilityState !== "visible") this.clearAll();
230.   };
231. 
232.   private clearAll(): void {
233.     this.state.clear();
234.     this.gamepadSnapshots.clear();
235.     this.releaseAllSyntheticKeys();
236.     this.closeMobileTextInput();
237.     this.cursorActive = false;
238.     this.updateCursor();
239.   }
240.

241.   private pollGamepads(timestamp: number): void {
242.     const pads = navigator.getGamepads();
243.     this.gamepadConnected = pads.some(Boolean);
244.     const connectedIndices = new Set<number>();
245.     for (const pad of pads) {
246.       if (!pad || pad.mapping !== "standard") continue;
247.       connectedIndices.add(pad.index);
248.       const previous = this.gamepadSnapshots.get(pad.index) ?? {
249.         buttons: [],
250.         axes: [],
251.       };
252.       const next: GamepadSnapshot = {
253.         buttons: pad.buttons.map((button) => button.pressed),
254.         axes: pad.axes.map((axis) => normalizeAnalogAxis(axis)),
255.       };
256.       for (const binding of STANDARD_GAMEPAD_BINDINGS) {
257.         this.updateGamepadBinding(pad.index, binding, previous, next, timestamp);
258.       }
259.       this.updateGamepadCursor(pad);
260.       if (
261.         this.cursorActive
262.         && next.buttons[11] === true
263.         && previous.buttons[11] !== true
264.       ) {
265.         this.clickCursor();
266.         inputSource.set("gamepad");
267.         this.updatePresentation("gamepad");
268.       }
269.       this.gamepadSnapshots.set(pad.index, next);
270.     }
271.     for (const index of this.gamepadSnapshots.keys()) {
272.       if (connectedIndices.has(index)) continue;
273.       this.gamepadSnapshots.delete(index);
274.       const released = this.state.releaseMatching(`gamepad:${index}:`);
275.       for (const entry of released) this.releaseSyntheticToken(entry.token);
276.     }
277.   }
278. 
279.   private updateGamepadBinding(
280.     index: number,
281.     binding: StandardGamepadBinding,
282.     previous: GamepadSnapshot,
283.     next: GamepadSnapshot,
284.     timestamp: number,
285.   ): void {
286.     const token = binding.button !== undefined
287.       ? `gamepad:${index}:button:${binding.button}`
288.       : `gamepad:${index}:axis:${binding.axis}:${binding.direction}`;
289.     const wasPressed = binding.button !== undefined
290.       ? previous.buttons[binding.button] === true
291.       : this.axisPressed(
292.         previous.axes[binding.axis ?? 0] ?? 0,
293.         binding.direction ?? 1,
294.       );
295.     const pressed = binding.button !== undefined
296.       ? next.buttons[binding.button] === true
297.       : this.axisPressed(
298.         next.axes[binding.axis ?? 0] ?? 0,
299.         binding.direction ?? 1,
300.       );
301.     if (pressed && !wasPressed) {
302.       const action = resolveGamepadAction(binding, this.getContext());
303.       if (
304.         this.cursorActive
305.         && (
306.           action.startsWith("navigate")
307.           || action.startsWith("move")
308.         )
309.       ) {
310.         this.cursorActive = false;
311.         this.updateCursor();
312.       }
313.       const event = this.state.press(token, action, "gamepad", timestamp);
314.       if (event) {
315.         this.dispatch(event);
316.       } else {
317.         const descriptor = this.keyForAction(this.contextualizeAction(action));
318.         if (descriptor) {
319.           this.pressSyntheticToken(token, descriptor, false, false);
320.         }
321.       }
322.     } else if (!pressed && wasPressed) {
323.       this.state.release(token);
324.       this.releaseSyntheticToken(token);
325.     }
326.   }
