332.   private updateGamepadCursor(gamepad: Gamepad): void {
333.     const x = normalizeAnalogAxis(gamepad.axes[2] ?? 0);
334.     const y = normalizeAnalogAxis(gamepad.axes[3] ?? 0);
335.     if (x === 0 && y === 0) return;
336.     const bounds = this.game.canvas.getBoundingClientRect();
337.     if (!this.cursorActive) {
338.       this.cursorX = bounds.left + bounds.width / 2;
339.       this.cursorY = bounds.top + bounds.height / 2;
340.     }
341.     const speed = 12;
342.     this.cursorX = Math.max(
343.       bounds.left,
344.       Math.min(bounds.right, this.cursorX + x * speed),
345.     );
346.     this.cursorY = Math.max(
347.       bounds.top,
348.       Math.min(bounds.bottom, this.cursorY + y * speed),
349.     );
350.     this.cursorActive = true;
351.     inputSource.set("gamepad");
352.     this.updatePresentation("gamepad");
353.     this.updateCursor();
354.     const mouseMove = new MouseEvent("mousemove", {
355.       bubbles: true,
356.       clientX: this.cursorX,
357.       clientY: this.cursorY,
358.     });
359.     this.syntheticEvents.add(mouseMove);
360.     this.game.canvas.dispatchEvent(mouseMove);
361.   }
