363.   private dispatch(event: SemanticInputEvent): void {
364.     inputSource.set(event.source);
365.     this.updatePresentation(event.source);
366.     const action = this.contextualizeAction(event.action);
367.     if (this.handleMobileTextInput(action)) return;
368.     if (action === "battleLogUp" || action === "battleLogDown") {
369.       this.dispatchWheel(action === "battleLogUp" ? -120 : 120);
370.       return;
371.     }
372.     const descriptor = event.token && event.repeated
373.       ? this.heldSyntheticKeys.get(event.token)
374.       : this.keyForAction(action);
375.     if (!descriptor) return;
376.     if (event.token) {
377.       this.pressSyntheticToken(event.token, descriptor, event.repeated);
378.     } else {
379.       this.dispatchKey("keydown", descriptor, event.repeated);
380.       window.setTimeout(() => this.dispatchKey("keyup", descriptor, false), 0);
381.     }
382.   }
