384.   private pressSyntheticToken(
385.     token: string,
386.     descriptor: KeyDescriptor,
387.     repeated: boolean,
388.     dispatchInitial = true,
389.   ): void {
390.     const existing = this.heldSyntheticKeys.get(token);
391.     if (repeated && existing) {
392.       this.dispatchKey("keydown", existing, true);
393.       return;
394.     }
395.     if (existing) return;
396.     this.heldSyntheticKeys.set(token, descriptor);
397.     const firstOwner = this.syntheticKeyOwnership.acquire(
398.       token,
399.       descriptor.code,
400.     );
401.     if (dispatchInitial && firstOwner) {
402.       this.dispatchKey("keydown", descriptor, false);
403.     }
404.   }
