406.   private releaseSyntheticToken(token: string): void {
407.     const descriptor = this.heldSyntheticKeys.get(token);
408.     if (!descriptor) return;
409.     this.heldSyntheticKeys.delete(token);
410.     const release = this.syntheticKeyOwnership.release(token);
411.     if (release?.finalOwner) {
412.       this.dispatchKey("keyup", descriptor, false);
413.     }
414.   }
