416.   private contextualizeAction(action: InputAction): InputAction {
417.     const context = this.getContext();
418.     if (context === "exploration" && action.startsWith("navigate")) {
419.       return action.replace("navigate", "move") as InputAction;
420.     }
421.     if (context === "cutscene" || context === "ending") {
422.       if (action === "confirm" || action === "interact") return "cutsceneAdvance";
423.       if (action === "cancel") return "cutsceneSkip";
424.     }
425.     if (context === "inventory") {
426.       const inventoryActions: Partial<Record<InputAction, InputAction>> = {
427.         navigateUp: "inventoryPrevious",
428.         navigateDown: "inventoryNext",
429.         navigateLeft: "inventoryPagePrevious",
430.         navigateRight: "inventoryPageNext",
431.         confirm: "inventoryPrimary",
432.       };
433.       return inventoryActions[action] ?? action;
434.     }
435.     if (context === "codex") {
436.       if (action === "interact") return "codexSearch";
437.       if (action === "battleTargetPrevious") return "codexCategoryPrevious";
438.       if (action === "battleTargetNext") return "codexCategoryNext";
439.     }
440.     return action;
441.   }
