443.   private keyForAction(action: InputAction): KeyDescriptor | undefined {
444.     if (
445.       (
446.         this.getContext() === "shop"
447.         || this.getContext() === "chronicle"
448.       )
449.       && action.startsWith("navigate")
450.     ) {
451.       const direction = action.slice("navigate".length);
452.       return { code: `Arrow${direction}`, key: `Arrow${direction}` };
453.     }
454.     if (
455.       this.getContext() === "characterCreation"
456.       && action.startsWith("navigate")
457.     ) {
458.       const direction = action.slice("navigate".length);
459.       return { code: `Arrow${direction}`, key: `Arrow${direction}` };
460.     }
461.     if (
462.       this.getContext() === "characterCreation"
463.       && (action === "confirm" || action === "interact")
464.     ) {
465.       return { code: "Enter", key: "Enter" };
466.     }
467.     return ACTION_KEYS[action];
468.   }
