470.   private dispatchKey(
471.     type: "keydown" | "keyup",
472.     descriptor: KeyDescriptor,
473.     repeat: boolean,
474.   ): void {
475.     const event = new KeyboardEvent(type, {
476.       bubbles: true,
477.       cancelable: true,
478.       code: descriptor.code,
479.       key: descriptor.key,
480.       repeat,
481.     });
482.     const keyCode = descriptor.keyCode ?? this.keyCodeFor(descriptor.code);
483.     Object.defineProperty(event, "keyCode", { value: keyCode });
484.     Object.defineProperty(event, "which", { value: keyCode });
485.     this.syntheticEvents.add(event);
486.     window.dispatchEvent(event);
487.   }
