514.   private releaseAllSyntheticKeys(): void {
515.     const descriptors = new Map<string, KeyDescriptor>();
516.     for (const descriptor of this.heldSyntheticKeys.values()) {
517.       descriptors.set(descriptor.code, descriptor);
518.     }
519.     this.heldSyntheticKeys.clear();
520.     this.syntheticKeyOwnership.clear();

521.     for (const descriptor of descriptors.values()) {
522.       this.dispatchKey("keyup", descriptor, false);
523.     }
524.   }
