553.   private createTouchControls(): void {
554.     const root = document.createElement("div");
555.     root.id = "touch-controls";
556.     root.setAttribute("aria-label", "Touch game controls");
557.     for (const definition of TOUCH_BUTTONS) {
558.       const button = document.createElement("button");
559.       button.type = "button";
560.       button.className = `touch-control ${definition.className}`;
561.       button.dataset.action = definition.action;
562.       button.dataset.action = definition.action;
563.       button.textContent = definition.label;
564.       button.setAttribute("aria-label", definition.action);
565.       button.addEventListener("pointerdown", (event) => {
566.         event.preventDefault();
567.         if (!HELD_TOUCH_ACTIONS.has(definition.action)) {
568.           inputSource.set("touch");
569.           this.updatePresentation("touch");
570.           return;
571.         }
572.         if (event.isTrusted) button.setPointerCapture(event.pointerId);
573.         const action = this.contextualizeAction(definition.action);
574.         const token = `touch:${event.pointerId}:${definition.action}`;
575.         const inputEvent = this.state.press(token, action, "touch", now());
576.         if (inputEvent) {
577.           this.dispatch(inputEvent);
578.         } else {
579.           const descriptor = this.keyForAction(action);
580.           if (descriptor) {
581.             this.pressSyntheticToken(token, descriptor, false, false);
582.           }
583.         }
584.       });
585.       const release = (event: PointerEvent): void => {
586.         if (!HELD_TOUCH_ACTIONS.has(definition.action)) return;
587.         const token = `touch:${event.pointerId}:${definition.action}`;
588.         this.state.release(token);
589.         window.setTimeout(() => this.releaseSyntheticToken(token), 40);
590.         if (button.hasPointerCapture(event.pointerId)) {
591.           button.releasePointerCapture(event.pointerId);
592.         }
593.       };
594.       button.addEventListener("pointerup", release);
595.       button.addEventListener("pointercancel", release);
596.       button.addEventListener("lostpointercapture", (event) => {
597.         this.state.release(`touch:${event.pointerId}:${definition.action}`);
598.       });
599.       button.addEventListener("click", (event) => {
600.         if (HELD_TOUCH_ACTIONS.has(definition.action)) return;
601.         event.preventDefault();
602.         const inputEvent = this.state.pulse(
603.           this.contextualizeAction(definition.action),
604.           "touch",
605.           now(),
606.         );
607.         if (inputEvent) this.dispatch(inputEvent);
608.       });
609.       root.append(button);
610.     }
611.     document.getElementById("game-inner")?.append(root);
612.     this.touchRoot = root;
613.     this.applyFeatureAvailability();
614.   }
