616.   private applyFeatureAvailability(): void {
617.     if (!this.touchRoot) return;
618.     for (const button of this.touchRoot.querySelectorAll<HTMLButtonElement>(
619.       ".touch-control",
620.     )) {
621.       const action = button.dataset.action;
622.       const featureId = action
623.         ? getInputActionFeature(action as InputAction)
624.         : undefined;
625.       button.hidden = featureId !== undefined
626.         && !featureAvailability.has(featureId);
627.     }
628.   }
