713.   private getContext(): InputContext {
714.     const key = this.getActiveSceneKey();
715.     if (key === "BootScene") {
716.       const state = document.getElementById("debug-state")?.textContent ?? "";
717.       return state.includes("Screen: title") ? "title" : "characterCreation";
718.     }
719.     if (key === "OverworldScene") {
720.       const state = document.getElementById("debug-state")?.textContent ?? "";
721.       if (state.includes("[PARTY:items")) return "inventory";
722.       if (state.includes("[GATHERING")) return "gathering";
723.       if (state.includes("[CHRONICLE]")) return "chronicle";
724.       if (
725.         state.includes("[PARTY:")
726.         || state.includes("[MENU]")
727.         || state.includes("[SAVE_SLOTS:")
728.         || state.includes("[TIPS")
729.         || state.includes("[WORLD_EVENT:")
730.       ) {
731.         return "overlay";
732.       }
733.       return "exploration";
734.     }
735.     if (key === "ShopScene") return "shop";
736.     if (key === "CodexScene") return "codex";
737.     if (key === "BattleScene") return "battle";
738.     if (key === "CutsceneScene") return "cutscene";
739.     if (key === "EndingScene") return "ending";
740.     if (key === "DefeatScene") return "result";
741.     return "overlay";
742.   }
743. }
