185. export function normalizeAnalogAxis(value: number, deadZone = 0.24): number {
186.   if (!Number.isFinite(value)) return 0;
187.   const clamped = Math.max(-1, Math.min(1, value));
188.   const magnitude = Math.abs(clamped);
189.   if (magnitude <= deadZone) return 0;
190.   const scaled = (magnitude - deadZone) / (1 - deadZone);
191.   return Math.sign(clamped) * scaled;
192. }
