11. async function gamePoint(
12.   page: Page,
13.   gameX: number,
14.   gameY: number,
15. ): Promise<{ x: number; y: number }> {
16.   const canvas = page.locator("#game-container canvas");
17.   await expect(canvas).toBeVisible();
18.   const bounds = await canvas.boundingBox();
19.   if (!bounds) throw new Error("Game canvas has no rendered bounds");
20.   return {
21.     x: bounds.x + (gameX / GAME_WIDTH) * bounds.width,
22.     y: bounds.y + (gameY / GAME_HEIGHT) * bounds.height,
23.   };
24. }
25. 
26. async function tapGame(
27.   page: Page,
28.   gameX: number,
29.   gameY: number,
30. ): Promise<void> {
31.   const point = await gamePoint(page, gameX, gameY);
32.   await page.touchscreen.tap(point.x, point.y);
33. }
