48. async function holdKey(
49.   page: Page,
50.   key: string,
51.   duration = 180,
52. ): Promise<void> {
53.   await page.keyboard.down(key);
54.   await page.waitForTimeout(duration);
55.   await page.keyboard.up(key);
56.   await page.waitForTimeout(120);
57. }
