59. async function drainOpening(page: Page, source: "touch" | "keyboard"): Promise<void> {
60.   let lastState = "";
61.   for (let step = 0; step < 80; step += 1) {
62.     const state = await page.locator("#debug-state").textContent() ?? "";
63.     lastState = state;
64.     if (state.includes("OVERWORLD")) return;
65.     if (source === "touch") {
66.       await page.locator('[data-action="confirm"]').tap();
67.     } else {
68.       await holdKey(page, "Space", 80);
69.     }
70.     await page.waitForTimeout(360);
71.   }
72.   throw new Error(`Timed out draining opening cutscenes: ${lastState}`);
73. }
