85. async function submitDebug(page: Page, command: string): Promise<void> {
86.   await page.locator("#debug-checkbox").check();
87.   const input = page.locator("#debug-cmd");
88.   if (await input.isVisible()) {
89.     await input.fill(command);
90.     await input.press("Enter");
91.   } else {
92.     await input.evaluate((element, value) => {
93.       const commandInput = element as HTMLInputElement;
94.       commandInput.value = value;
95.       commandInput.dispatchEvent(new Event("input", { bubbles: true }));
96.       commandInput.dispatchEvent(new KeyboardEvent("keydown", {
97.         key: "Enter",
98.         code: "Enter",
99.         bubbles: true,
100.       }));
101.     }, command);
102.   }
103.   if (!command.startsWith("/event trigger")) {
104.     await page.locator("#game-container canvas").click();
105.   }
106. }
