108. async function setGamepadAxes(page: Page, axes: number[]): Promise<void> {
109.   await page.evaluate((values) => {
110.     (window as typeof window & {
111.       __setGamepadAxes(axes: number[]): void;
112.     }).__setGamepadAxes(values);
113.   }, axes);
114. }
