116. function cursorAxis(delta: number): number {
117.   const distance = Math.abs(delta);
118.   if (distance < 20) return 0;
119.   return Math.sign(delta) * Math.min(0.7, Math.max(0.35, distance / 120));
120. }
121. 
122. async function moveGamepadCursor(
123.   page: Page,
124.   gameX: number,
125.   gameY: number,
126. ): Promise<void> {
127.   const target = await gamePoint(page, gameX, gameY);
128.   for (let attempt = 0; attempt < 240; attempt += 1) {
129.     const bounds = await page.locator("#gamepad-cursor").boundingBox();
130.     if (bounds) {
131.       const cursorX = bounds.x + bounds.width / 2;
132.       const cursorY = bounds.y + bounds.height / 2;
133.       const dx = target.x - cursorX;
134.       const dy = target.y - cursorY;
135.       if (Math.abs(dx) < 20 && Math.abs(dy) < 20) {
136.         await setGamepadAxes(page, [0, 0, 0, 0]);
137.         return;
138.       }
139.       await setGamepadAxes(page, [
140.         0,
141.         0,
142.         cursorAxis(dx),
143.         cursorAxis(dy),
144.       ]);
145.     } else {
146.       await setGamepadAxes(page, [0, 0, 0, 0.8]);
147.     }
148.     await page.waitForTimeout(75);
149.   }
150.   await setGamepadAxes(page, [0, 0, 0, 0]);
151.   throw new Error("Timed out positioning gamepad cursor");
152. }
