174. function publishLayoutReport(scene: Phaser.Scene): void {
175.   const report = auditSceneLayout(scene);
176.   scene.game.canvas.dataset.layoutOverlapCount = String(report.overlapCount);
177.   scene.game.canvas.dataset.layoutClippingCount = String(report.clippingCount);
178.   scene.game.canvas.dataset.layoutScene = report.scene;
179.   const element = getReportElement();
180.   if (element) element.textContent = JSON.stringify(report);
