183. export function installSceneLayoutAudit(scene: Phaser.Scene): void {
184.   if (!isLocalDev() || installedScenes.has(scene)) return;
185.   installedScenes.add(scene);
186.   let lastAudit = 0;
187.   const audit = (time: number): void => {
188.     if (time - lastAudit < 200) return;
189.     lastAudit = time;
190.     publishLayoutReport(scene);
191.   };
192.   scene.events.on("postupdate", audit);
193.   scene.events.once("shutdown", () => {
194.     scene.events.off("postupdate", audit);
195.     sceneGroups.delete(scene);
196.     installedScenes.delete(scene);
197.   });
198.   publishLayoutReport(scene);
199. }
