98. export function insetRect(
99.   rect: LayoutRect,
100.   insets: Partial<LayoutInsets>,
101. ): LayoutRect {
102.   const top = finiteNonNegative(insets.top ?? 0);
103.   const right = finiteNonNegative(insets.right ?? 0);
104.   const bottom = finiteNonNegative(insets.bottom ?? 0);
105.   const left = finiteNonNegative(insets.left ?? 0);
106.   return {
107.     x: rect.x + left,
108.     y: rect.y + top,
109.     width: Math.max(0, rect.width - left - right),
110.     height: Math.max(0, rect.height - top - bottom),
111.   };
112. }
