114. export function clampRectToViewport(
115.   rect: LayoutRect,
116.   viewport: LayoutRect,
117. ): LayoutRect {
118.   const width = Math.min(finiteNonNegative(rect.width), viewport.width);
119.   const height = Math.min(finiteNonNegative(rect.height), viewport.height);
120.   return {
121.     x: Math.min(
122.       Math.max(rect.x, viewport.x),
123.       viewport.x + viewport.width - width,
124.     ),
125.     y: Math.min(
126.       Math.max(rect.y, viewport.y),
127.       viewport.y + viewport.height - height,
128.     ),
129.     width,
130.     height,
131.   };
132. }
