134. export function centeredRect(
135.   viewport: LayoutRect,
136.   requestedSize: LayoutSize,
137.   padding: Partial<LayoutInsets> = ZERO_INSETS,
138. ): LayoutRect {
139.   const available = insetRect(viewport, padding);
140.   const width = Math.min(finiteNonNegative(requestedSize.width), available.width);
141.   const height = Math.min(
142.     finiteNonNegative(requestedSize.height),
143.     available.height,
144.   );
145.   return {
146.     x: available.x + Math.floor((available.width - width) / 2),
147.     y: available.y + Math.floor((available.height - height) / 2),
148.     width,
149.     height,
150.   };
151. }
