153. export function layoutVerticalStack(
154.   items: readonly StackItem[],
155.   options: {
156.     x?: number;
157.     y?: number;
158.     gap?: number;
159.     align?: "start" | "center" | "end";
160.     width?: number;
161.   } = {},
162. ): StackLayout {
163.   const x = options.x ?? 0;
164.   const y = options.y ?? 0;
165.   const gap = finiteNonNegative(options.gap ?? 0);
166.   const naturalWidth = items.reduce(
167.     (max, item) => Math.max(max, finiteNonNegative(item.width)),
168.     0,
169.   );
170.   const width = Math.max(naturalWidth, finiteNonNegative(options.width ?? 0));
171.   const align = options.align ?? "start";
172.   let cursorY = y;
173.   const positioned = items.map((item) => {
174.     const itemWidth = finiteNonNegative(item.width);
175.     const itemHeight = finiteNonNegative(item.height);
176.     const offsetX = align === "center"
177.       ? (width - itemWidth) / 2
178.       : align === "end"
179.       ? width - itemWidth
180.       : 0;
181.     const result = {
182.       ...item,
183.       width: itemWidth,
184.       height: itemHeight,
185.       x: x + offsetX,
186.       y: cursorY,
187.     };
188.     cursorY += itemHeight + gap;
189.     return result;
190.   });
191.   return {
192.     items: positioned,
193.     width,
194.     height: items.length === 0 ? 0 : cursorY - y - gap,
195.   };
196. }
