198. export function layoutResponsiveGrid(
199.   options: GridLayoutOptions,
200. ): GridLayout {
201.   const availableWidth = finiteNonNegative(options.availableWidth);
202.   const minColumnWidth = Math.max(1, finiteNonNegative(options.minColumnWidth));
203.   const columnGap = finiteNonNegative(options.columnGap);
204.   const rowGap = finiteNonNegative(options.rowGap);
205.   const fittingColumns = Math.max(
206.     1,
207.     Math.floor((availableWidth + columnGap) / (minColumnWidth + columnGap)),
208.   );
209.   const columns = Math.max(
210.     1,
211.     Math.min(options.maxColumns ?? fittingColumns, fittingColumns),
212.   );
213.   const columnWidth = Math.max(
214.     0,
215.     (availableWidth - columnGap * (columns - 1)) / columns,
216.   );
217.   const rows = Math.ceil(options.itemHeights.length / columns);
218.   const rowHeights = Array.from({ length: rows }, () => 0);
219.   options.itemHeights.forEach((height, index) => {
220.     const row = Math.floor(index / columns);
221.     rowHeights[row] = Math.max(rowHeights[row], finiteNonNegative(height));
222.   });
223.   const rowOffsets: number[] = [];
224.   let cursorY = 0;
225.   for (const height of rowHeights) {
226.     rowOffsets.push(cursorY);
227.     cursorY += height + rowGap;
228.   }
229.   const cells = options.itemHeights.map((height, index) => {
230.     const row = Math.floor(index / columns);
231.     const column = index % columns;
232.     return {
233.       index,
234.       row,
235.       column,
236.       x: column * (columnWidth + columnGap),
237.       y: rowOffsets[row],
238.       width: columnWidth,
239.       height: finiteNonNegative(height),
