251. export function paginateMeasuredItems(
252.   itemHeights: readonly number[],
253.   availableHeight: number,
254.   gap = 0,
255. ): number[][] {
256.   const heightLimit = finiteNonNegative(availableHeight);
257.   const safeGap = finiteNonNegative(gap);
