77. async function drainOpening(page: Page, source: "touch" | "keyboard"): Promise<void> {
78.   let lastState = "";
79.   for (let step = 0; step < 80; step += 1) {
80.     const state = await page.locator("#debug-state").textContent() ?? "";
81.     lastState = state;
82.     if (state.includes("OVERWORLD")) return;
83.     if (source === "touch") {
84.       await page.locator('[data-action="confirm"]').tap();
85.     } else {
86.       await holdKey(page, "Space", 80);
87.     }
88.     await page.waitForTimeout(360);
89.   }
90.   throw new Error(`Timed out draining opening cutscenes: ${lastState}`);
91. }
