103. async function submitDebug(page: Page, command: string): Promise<void> {
104.   await page.locator("#debug-checkbox").check();
105.   const input = page.locator("#debug-cmd");
106.   if (await input.isVisible()) {
107.     await input.fill(command);
108.     await input.press("Enter");
109.   } else {
110.     await input.evaluate((element, value) => {
111.       const commandInput = element as HTMLInputElement;
112.       commandInput.value = value;
113.       commandInput.dispatchEvent(new Event("input", { bubbles: true }));
114.       commandInput.dispatchEvent(new KeyboardEvent("keydown", {
115.         key: "Enter",
116.         code: "Enter",
117.         bubbles: true,
118.       }));
119.     }, command);
120.   }
121.   if (!command.startsWith("/event trigger")) {
122.     await page.locator("#game-container canvas").click();
123.   }
124. }
