126. async function setGamepadAxes(page: Page, axes: number[]): Promise<void> {
127.   await page.evaluate((values) => {
128.     (window as typeof window & {
129.       __setGamepadAxes(axes: number[]): void;
130.     }).__setGamepadAxes(values);
131.   }, axes);
132. }
