140. async function moveGamepadCursor(
141.   page: Page,
142.   gameX: number,
143.   gameY: number,
144. ): Promise<void> {
145.   const target = await gamePoint(page, gameX, gameY);
146.   for (let attempt = 0; attempt < 240; attempt += 1) {
147.     const bounds = await page.locator("#gamepad-cursor").boundingBox();
148.     if (bounds) {
149.       const cursorX = bounds.x + bounds.width / 2;
150.       const cursorY = bounds.y + bounds.height / 2;
151.       const dx = target.x - cursorX;
152.       const dy = target.y - cursorY;
153.       if (Math.abs(dx) < 20 && Math.abs(dy) < 20) {
154.         await setGamepadAxes(page, [0, 0, 0, 0]);
155.         return;
156.       }
157.       await setGamepadAxes(page, [
158.         0,
159.         0,
160.         cursorAxis(dx),
161.         cursorAxis(dy),
162.       ]);
163.     } else {
164.       await setGamepadAxes(page, [0, 0, 0, 0.8]);
165.     }
166.     await page.waitForTimeout(75);
167.   }
168.   await setGamepadAxes(page, [0, 0, 0, 0]);
169.   throw new Error("Timed out positioning gamepad cursor");
170. }
